//! Studio TypeScript protocol codegen (R6). `packages/studio-protocol` is
//! generated output regenerated by `xtask gen-check`; a hand edit is rejected.
//! The pinned generator version is [`GENERATOR_VERSION`]; the emitted source
//! carries a `@generated` banner and is never hand-edited.
//! REQ: REQ-STUDIO-006 (generated protocol; hand edits rejected).

use std::fs;
use std::path::Path;

use anyhow::{Context, Result, bail};

/// Pinned generator version (R6 fingerprint). REQ: REQ-STUDIO-006.
pub const GENERATOR_VERSION: &str = "1";

/// Repository-relative path of the generated TypeScript module.
/// REQ: REQ-STUDIO-006.
pub const OUTPUT_REL: &str = "packages/studio-protocol/src/index.ts";

/// The generated TypeScript source (the codegen output). REQ: REQ-STUDIO-006.
pub const TS_SOURCE: &str = r#"// @generated by drm-studio-codegen v1 (pinned); do not edit by hand.
// Regenerate with `cargo xtask gen-check`; hand edits fail CI (R6, REQ-STUDIO-006).
// Mirrors the Rust request/response/command enums in `crates/drm-cli/src/studio`.

export type Capability =
  | "workspace.v2"
  | "extensions.web"
  | "binaryStreams.v1"
  | "runtime.stats"
  | "trust";

export interface Hello {
  method: "hello";
  protocol_version: number;
  client_version: string;
}

export interface HelloAck {
  result: "hello_ack";
  protocol_version: number;
  host_version: string;
  capabilities: Capability[];
}

export type Severity = "error" | "warning" | "runtime" | "info";

export interface Diagnostic {
  severity: Severity;
  message: string;
}

export interface WorkspaceSnapshot {
  revision: number;
  model: string;
  problems: Diagnostic[];
}

export interface VerifySummary {
  green: boolean;
  findings: string[];
}

export interface PackageSpec {
  name: string;
  path: string | null;
}

export interface NodeSpec {
  name: string;
  publishes: string[];
  consumes: string[];
}

export interface TopicSpec {
  path: string;
  fields: number;
}

export interface ComputeSpec {
  name: string;
  platform: string | null;
}

export interface LinkSpec {
  from: string;
  to: string;
  transport: string | null;
}

export interface RunConfig {
  nodes: string[];
  leave_running: boolean;
}

export type SessionStatus = "running" | "stopped";

export type ProcessStatus = "running" | "stopped" | { exited: number };

export interface NodeProcessView {
  node: string;
  pid: number | null;
  status: ProcessStatus;
  stdout: string;
  stderr: string;
}

export interface RunSessionView {
  id: string;
  started_at: number;
  status: SessionStatus;
  leave_running: boolean;
  nodes: NodeProcessView[];
}

export interface RuntimeStats {
  session: string;
  node: string;
  pid: number | null;
  status: ProcessStatus;
}

export type ModelCommand =
  | ({ op: "package_create" } & PackageSpec)
  | { op: "package_rename"; from: string; to: string }
  | { op: "package_delete"; name: string }
  | ({ op: "node_create" } & NodeSpec)
  | ({ op: "node_update" } & NodeSpec)
  | { op: "node_delete"; name: string }
  | ({ op: "topic_create" } & TopicSpec)
  | ({ op: "topic_update" } & TopicSpec)
  | { op: "topic_rename"; from: string; to: string }
  | { op: "topic_delete"; path: string }
  | ({ op: "compute_create" } & ComputeSpec)
  | ({ op: "compute_update" } & ComputeSpec)
  | ({ op: "link_create" } & LinkSpec)
  | ({ op: "link_update" } & LinkSpec);

export type StudioRequest =
  | Hello
  | { method: "open_workspace"; path: string }
  | { method: "snapshot" }
  | { method: "verify" }
  | { method: "mutate"; base_revision: number; command: ModelCommand }
  | { method: "build_start"; target: string | null }
  | { method: "build_cancel" }
  | { method: "run_start"; config: RunConfig }
  | { method: "run_stop"; session: string }
  | { method: "run_restart"; session: string }
  | { method: "run_sessions" }
  | { method: "runtime_stats" }
  | { method: "undo"; changeset: string; force: boolean }
  | { method: "subscribe_telemetry"; channels: string[] };

export type StudioResponse =
  | HelloAck
  | ({ result: "snapshot" } & WorkspaceSnapshot)
  | ({ result: "verify" } & VerifySummary)
  | {
      result: "mutation_result";
      revision: number;
      render: string;
      changeset: string;
    }
  | { result: "conflict"; revision: number }
  | { result: "conflict_external_changed"; changeset: string }
  | { result: "build_accepted"; revision: number }
  | { result: "run_accepted"; session: string }
  | { result: "run_sessions"; sessions: RunSessionView[] }
  | { result: "runtime_stats"; stats: RuntimeStats[] }
  | { result: "telemetry_token"; token: string }
  | { result: "error"; code: string; message: string };
"#;

/// Renders the generated TypeScript source. REQ: REQ-STUDIO-006.
#[must_use]
pub fn render() -> &'static str {
    TS_SOURCE
}

/// Checks the committed TS module against a fresh render.
/// REQ: REQ-STUDIO-006.
///
/// # Errors
/// A missing or hand-edited generated module.
pub fn check(root: &Path) -> Result<()> {
    let path = root.join(OUTPUT_REL);
    let committed = match fs::read_to_string(&path) {
        Ok(text) => text,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            bail!(
                "gen-check: missing generated TS module `{}`",
                path.display()
            );
        }
        Err(e) => {
            return Err(e).with_context(|| format!("gen-check: read `{}`", path.display()));
        }
    };
    if committed != render() {
        bail!(
            "gen-check: hand-edited or stale generated TS module `{}`",
            path.display()
        );
    }
    let banner = format!("@generated by drm-studio-codegen v{GENERATOR_VERSION}");
    if !committed.contains(&banner) {
        bail!("gen-check: TS module missing the pinned generator banner");
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use std::path::PathBuf;
    use std::sync::atomic::{AtomicU64, Ordering};

    /// REQ: REQ-STUDIO-006 — a freshly rendered module is clean; a hand edit is
    /// detected (red→green fixture).
    #[test]
    fn detects_hand_edited_ts_module() {
        static COUNTER: AtomicU64 = AtomicU64::new(0);
        let n = COUNTER.fetch_add(1, Ordering::Relaxed);
        let root = std::env::temp_dir().join(format!("drm-studio-ts-{}-{n}", std::process::id()));
        let dir = root.join("packages/studio-protocol/src");
        std::fs::create_dir_all(&dir).unwrap_or_else(|e| unreachable!("mkdir: {e}"));
        let path: PathBuf = dir.join("index.ts");
        std::fs::write(&path, super::render()).unwrap_or_else(|e| unreachable!("write: {e}"));
        super::check(&root).unwrap_or_else(|e| unreachable!("clean: {e}"));

        let mut body = std::fs::read_to_string(&path).unwrap_or_else(|e| unreachable!("read: {e}"));
        body.push_str("// hand edited\n");
        std::fs::write(&path, body).unwrap_or_else(|e| unreachable!("write edit: {e}"));
        assert!(super::check(&root).is_err(), "hand edit must be detected");
        let _ = std::fs::remove_dir_all(&root);
    }
}
